// Generated by Claude

import { useEffect, useRef, useState } from 'react'
import { ANIMATIONS, WIDTH, HEIGHT, drawFrame } from './catSprites'

// mode: 'idle' | 'eating' | 'petted'
// scale: koľko obrazovkových pixelov má jeden pixel mačky
export default function PixelCat({ mode = 'idle', scale = 8, speed = 220 }) {
  const canvasRef = useRef(null)
  const [frameIndex, setFrameIndex] = useState(0)

  // pri zmene animácie začni od prvej snímky
  useEffect(() => setFrameIndex(0), [mode])

  // posúvaj snímky
  useEffect(() => {
    const id = setInterval(() => setFrameIndex(i => i + 1), speed)
    return () => clearInterval(id)
  }, [speed])

  // nakresli aktuálnu snímku
  useEffect(() => {
    const frames = ANIMATIONS[mode]
    drawFrame(canvasRef.current.getContext('2d'), frames[frameIndex % frames.length], scale)
  }, [mode, frameIndex, scale])

  return (
    <canvas
      ref={canvasRef}
      width={WIDTH * scale}
      height={HEIGHT * scale}
      style={{ imageRendering: 'pixelated' }}
      aria-label="Pixel mačka"
    />
  )
}
